Ltac split_cells H n H1 H2 :=
  lazymatch type of H with rw_cells ?sg ?m (?base + ?off) ?cs =>
    let l1 := eval cbv [firstn skipn] in (firstn n cs) in
    let l2 := eval cbv [firstn skipn] in (skipn n cs) in
    let k := eval cbv in (off + Z.of_nat (cells_size l1))%Z in
    destruct (proj1 (rw_cells_app sg m (base + off) l1 l2) H) as [H1 H2];
    replace (base + off + Z.of_nat (cells_size l1))%Z with (base + k)%Z in H2
      by (cbv [cells_size csize Z.of_nat Pos.of_succ_nat Pos.succ Pos.add Pos.mul Nat.add]; lia)
  end.
Ltac split_cells0 H n H1 H2 :=
  lazymatch type of H with rw_cells ?sg ?m ?base ?cs =>
    let l1 := eval cbv [firstn skipn] in (firstn n cs) in
    let l2 := eval cbv [firstn skipn] in (skipn n cs) in
    let k := eval cbv in (Z.of_nat (cells_size l1))%Z in
    destruct (proj1 (rw_cells_app sg m base l1 l2) H) as [H1 H2];
    replace (base + Z.of_nat (cells_size l1))%Z with (base + k)%Z in H2
      by (cbv [cells_size csize Z.of_nat Pos.of_succ_nat Pos.succ Pos.add Pos.mul Nat.add]; lia)
  end.
(* [comment removed for export] *)
Ltac join_cells H1 H2 :=
  lazymatch type of H1 with rw_cells ?sg ?m ?A ?l1 =>
  lazymatch type of H2 with rw_cells _ _ ?A2 ?l2 =>
    let J := fresh "J" in
    assert (J : rw_cells sg m A (l1 ++ l2));
    [ apply (proj2 (rw_cells_app sg m A l1 l2)); split; [exact H1|];
      replace (A + Z.of_nat (cells_size l1))%Z with A2 by (cbv [cells_size csize Z.of_nat Pos.of_succ_nat Pos.succ Pos.add Pos.mul Nat.add]; lia); exact H2
    | clear H1 H2; cbn [app] in J; rename J into H1 ]
  end end.

